<td><select name="plans[<?=(int)$row['id']?>]" aria-label="Plan de <?=$e($row['display_name'])?>" <?=$row['enabled']?'':'disabled'?>><?php foreach($data['plans'] as $code=>$label):?><option value="<?=$e($code)?>" <?=$row['plan']===$code?'selected':''?>><?=$e($label)?></option><?php endforeach?></select></td>
